// 由 assets/docs*.js 產生的元件名稱與說明（和網頁版文件相同）。
// ignore_for_file: lines_longer_than_80_chars

typedef DocMeta = ({String id, String group, String name, String en, String desc, List<String> when});

const docGroups = <String, String>{"general": "通用", "nav": "導覽", "entry": "資料輸入", "display": "資料展示", "feedback": "回饋"};

const docs = <DocMeta>[
  (id: "button", group: "general", name: "按鈕", en: "Button", desc: "觸發一個操作。主要按鈕用珊瑚紅，一個區塊最多一個；其他動作用次要、外框或文字按鈕。", when: <String>["送出表單、開啟對話框等主要操作", "同一區塊有多個操作時，用不同變體區分主次", "需要載入狀態時加上 is-loading，避免重複送出"]),
  (id: "tabs", group: "nav", name: "標籤頁", en: "Tabs", desc: "在同一個區域切換不同內容。底線指示器用 transform 滑到選中的標籤，內容切換時輕微淡入。", when: <String>["同一層級、互斥的內容分組，例如「總覽／設定／紀錄」", "選項 2–6 個；超過時考慮下拉選單或側邊導覽", "需要比較的內容不要拆在不同標籤裡"]),
  (id: "pagination", group: "nav", name: "分頁", en: "Pagination", desc: "把長列表分成多頁。只要寫總頁數和目前頁數，按鈕與省略號由 aicde-ui.js 產生。", when: <String>["資料量大、需要跳到特定頁數時", "使用者需要知道「總共有多少」", "連續瀏覽的內容（動態、消息）改用無限捲動或「載入更多」"]),
  (id: "dropdown", group: "nav", name: "下拉選單", en: "Dropdown", desc: "把次要的操作收進選單。選單從觸發按鈕的位置長出來，點外面或按 Esc 關閉。", when: <String>["操作超過 3 個，不想全部攤在畫面上", "「更多」按鈕裡的次要操作", "需要選一個值時，改用下拉選擇（select）"]),
  (id: "input", group: "entry", name: "輸入框", en: "Input", desc: "讓使用者輸入文字。搭配 a-field 加上標籤與說明文字，錯誤時整組變紅。", when: <String>["需要使用者輸入一行文字", "表單欄位需要標籤、提示或錯誤訊息", "搜尋框可以在左側放圖示"]),
  (id: "switch", group: "entry", name: "開關", en: "Switch", desc: "切換兩種狀態，切換後立即生效。底層是原生 checkbox，鍵盤與螢幕報讀器都能使用。", when: <String>["設定項目的開／關，切換後立即生效", "需要按「儲存」才生效的選項，改用 checkbox"]),
  (id: "card", group: "display", name: "卡片", en: "Card", desc: "把一組相關資訊包在一起：圖片、標題、說明與操作。可點擊的卡片 hover 時浮起。", when: <String>["列表中每個項目資訊較多，例如文章、商品、專案", "需要整張可以點進去時，用 a-card--interactive 並把卡片做成 a 標籤", "資訊很少時直接用列表，不要硬包成卡片"]),
  (id: "modal", group: "feedback", name: "對話框", en: "Modal", desc: "打斷目前流程，請使用者確認或補充資訊。用原生 dialog，焦點鎖定與 Esc 關閉都是瀏覽器內建的。", when: <String>["需要使用者確認才能繼續，例如刪除", "簡短的表單，不想離開目前頁面", "只是告知訊息時改用 Toast，不要打斷使用者"]),
  (id: "toast", group: "feedback", name: "通知", en: "Toast", desc: "操作完成後的短暫回饋，不打斷使用者。從右下角滑入，3.2 秒後自動消失，滑鼠停留時暫停。", when: <String>["回報操作結果：已儲存、已複製、上傳失敗", "訊息不需要使用者回應", "需要使用者決定的事改用對話框"]),
  (id: "divider", group: "general", name: "分隔線", en: "Divider", desc: "區隔內容區塊。可以加文字，也可以直立放在文字之間。", when: <String>["同一張卡片或表單裡，把不同段落分開", "分隔一排連結或操作，用直立分隔線", "區塊之間已經有足夠留白時，不需要再加線"]),
  (id: "breadcrumb", group: "nav", name: "麵包屑", en: "Breadcrumb", desc: "顯示目前頁面在網站裡的位置，並能快速回到上層。", when: <String>["網站有 3 層以上的階層", "使用者可能從搜尋直接進到深層頁面", "只有一兩層的網站不需要"]),
  (id: "steps", group: "nav", name: "步驟條", en: "Steps", desc: "把一個長流程拆成幾步，讓使用者知道現在在哪、還剩多少。", when: <String>["註冊、結帳、設定精靈等有固定順序的流程", "步驟 3–5 個最容易理解", "沒有先後順序的內容改用標籤頁"]),
  (id: "textarea", group: "entry", name: "多行輸入", en: "Textarea", desc: "輸入較長的文字。設定 maxlength 時會自動顯示字數，接近上限時變紅。", when: <String>["留言、描述、意見回饋等超過一行的內容", "只需要一行的內容用輸入框", "需要格式（粗體、清單）時改用編輯器"]),
  (id: "select", group: "entry", name: "下拉選擇", en: "Select", desc: "從固定選項中選一個。用原生 select，手機上會跳出系統的選擇器。", when: <String>["選項 5 個以上、只能選一個", "選項 2–4 個時，用單選或分段控制器更快", "需要搜尋選項時改用自動完成"]),
  (id: "checkbox", group: "entry", name: "核取方塊", en: "Checkbox", desc: "從多個選項中勾選任意幾個。按下時微縮，勾選後換成珊瑚紅。", when: <String>["可以複選的選項", "需要按「送出」才生效的設定", "單一、立即生效的開關改用開關元件"]),
  (id: "radio", group: "entry", name: "單選", en: "Radio", desc: "從幾個選項中只能選一個，所有選項同時攤開，一眼就能比較。", when: <String>["2–5 個互斥選項，而且需要讓使用者看到全部", "選項太多時改用下拉選擇", "選項短、像在切換檢視時，改用分段控制器"]),
  (id: "segmented", group: "entry", name: "分段控制器", en: "Segmented", desc: "2–5 個短選項的單選，像按鈕群組。底層是 radio，可以直接放進表單。", when: <String>["切換檢視方式：列表／格狀、日／週／月", "選項短、數量少", "切換的是不同頁面內容時，用標籤頁"]),
  (id: "slider", group: "entry", name: "滑桿", en: "Slider", desc: "在一個範圍內拖曳選值。用原生 range，鍵盤方向鍵也能調整。", when: <String>["數值精確度不重要，例如音量、透明度", "使用者想邊拖邊看效果", "需要輸入精確數字時，改用輸入框"]),
  (id: "tag", group: "display", name: "標籤", en: "Tag", desc: "標示分類、狀態或關鍵字。可以加上關閉按鈕讓使用者移除。", when: <String>["文章分類、篩選條件、狀態", "可移除的篩選條件用有關閉按鈕的版本", "需要點擊觸發動作時用按鈕，不要用標籤"]),
  (id: "badge", group: "display", name: "徽章", en: "Badge", desc: "在圖示或頭像右上角顯示數量或紅點，提醒有新內容。", when: <String>["未讀訊息、通知數量", "只要提醒「有新的」不需要數字時用紅點", "數字超過 99 顯示 99+"]),
  (id: "avatar", group: "display", name: "頭像", en: "Avatar", desc: "代表使用者或團隊。沒有照片時顯示名字的第一個字。", when: <String>["留言、成員列表、帳號選單", "多位成員用頭像群組，重疊排列", "物件或專案用方形頭像"]),
  (id: "tooltip", group: "display", name: "文字提示", en: "Tooltip", desc: "滑鼠停留或鍵盤聚焦時顯示簡短說明。純 CSS，只要加一個屬性。", when: <String>["只有圖示的按鈕，說明它是做什麼的", "補充說明，不是必要資訊", "手機上沒有 hover，重要資訊不要只放在提示裡"]),
  (id: "collapse", group: "display", name: "摺疊面板", en: "Collapse", desc: "把次要內容收起來，需要時再展開。用原生 details，不需要 JS。", when: <String>["常見問題、進階設定", "內容很長但多數人只看其中一兩段", "重要資訊不要藏在摺疊裡"]),
  (id: "table", group: "display", name: "表格", en: "Table", desc: "比較多筆資料的多個欄位。數字靠右、等寬數字，方便上下對齊比較。", when: <String>["需要比較、排序的結構化資料", "欄位多時外層會出現橫向捲動，不會撐破版面", "手機上欄位太多時，考慮改成卡片列表"]),
  (id: "empty", group: "display", name: "空狀態", en: "Empty", desc: "沒有資料時告訴使用者發生了什麼，以及下一步可以做什麼。", when: <String>["列表、搜尋結果、收件匣沒有內容", "第一次使用、還沒建立任何東西", "附上一個明確的行動按鈕"]),
  (id: "alert", group: "feedback", name: "警示", en: "Alert", desc: "在頁面中顯示需要注意的訊息，會一直留在畫面上，直到問題解決。", when: <String>["表單整體錯誤、系統公告、帳號狀態", "訊息需要留著讓使用者回頭看", "短暫的操作結果改用通知 Toast"]),
  (id: "progress", group: "feedback", name: "進度條", en: "Progress", desc: "顯示一個操作完成了多少。用 --v（0 到 1）控制進度，變化時平滑移動。", when: <String>["上傳、下載、匯出等超過 1 秒的操作", "知道總量時顯示百分比；不知道時用不確定模式", "不到 1 秒的操作不需要進度條"]),
  (id: "skeleton", group: "feedback", name: "骨架屏", en: "Skeleton", desc: "內容載入中時，先畫出大致的版面形狀，讓等待感覺比較短。", when: <String>["載入時間 300ms 以上、版面結構已知", "形狀盡量接近真實內容", "很短的載入不要閃一下骨架，直接顯示內容"]),
  (id: "spinner", group: "feedback", name: "載入中", en: "Spinner", desc: "表示正在處理，但不知道要多久。適合小範圍、短時間的等待。", when: <String>["按鈕送出後、區塊重新整理時", "整頁載入用骨架屏，體驗比較好", "按鈕裡的載入狀態直接用按鈕的 is-loading"]),
  (id: "menu", group: "nav", name: "側邊選單", en: "Menu", desc: "後台或文件網站的主要導覽。子選單用原生 details 展開，目前頁面用 aria-current 標記。", when: <String>["頁面多、需要常駐的導覽", "選單層級最多兩層，再深就難找", "頁面少於 5 個時，放在頂部導覽列就好"]),
  (id: "date", group: "entry", name: "日期時間", en: "Date Picker", desc: "選日期或時間。用原生 input，手機會跳出系統的選擇器，鍵盤也能直接輸入。", when: <String>["生日、預約、篩選期間", "日期範圍用兩個輸入框，中間加箭頭", "需要同時看到整個月的空檔時，改用日曆元件"]),
  (id: "upload", group: "entry", name: "上傳", en: "Upload", desc: "點擊或把檔案拖進來上傳。拖進來時框線變珊瑚紅並微微放大，選好的檔案列在下方。", when: <String>["上傳圖片、文件、匯入資料", "寫清楚接受的格式與大小上限", "只上傳一張頭像時，直接點頭像更直覺"]),
  (id: "rating", group: "entry", name: "評分", en: "Rating", desc: "用星星打分數。底層是 radio，純 CSS；滑過時預覽分數，按下時星星微縮。", when: <String>["商品評價、滿意度調查", "只需要讚／不讚時用兩個按鈕就好", "顯示平均分數時用停用狀態"]),
  (id: "statistic", group: "display", name: "統計數值", en: "Statistic", desc: "在儀表板顯示重點數字與變化。進到畫面時數字從 0 跳到目標值，只播一次。", when: <String>["儀表板的 KPI", "加上和上期比較的漲跌", "數字很多時改用表格"]),
  (id: "timeline", group: "display", name: "時間軸", en: "Timeline", desc: "按時間順序列出事件，例如訂單進度或更新紀錄。", when: <String>["訂單、物流、審核進度", "版本更新紀錄", "步驟還沒發生、需要引導時，用步驟條"]),
  (id: "list", group: "display", name: "列表", en: "List", desc: "一列一筆資料：頭像、標題、說明、右側資訊。文字過長自動省略。", when: <String>["成員、檔案、通知等同類型資料", "每筆資料欄位少於 3 個", "欄位多、需要比較時改用表格"]),
  (id: "descriptions", group: "display", name: "描述列表", en: "Descriptions", desc: "成對顯示「欄位：值」，例如訂單資訊、個人資料。手機上自動變成單欄。", when: <String>["詳情頁的唯讀資料", "欄位名稱短、值也短", "要編輯時換成表單"]),
  (id: "kbd", group: "display", name: "鍵盤按鍵", en: "Kbd", desc: "在說明文字中標示鍵盤快捷鍵，底部加厚模擬實體按鍵。", when: <String>["說明快捷鍵", "選單項目右側的快捷鍵提示", "Mac 與 Windows 不同時兩者都寫"]),
  (id: "drawer", group: "feedback", name: "抽屜", en: "Drawer", desc: "從畫面側邊滑出的面板，放進一步的細節或表單，不用離開目前頁面。和對話框共用開關方式。", when: <String>["查看或編輯一筆資料的詳情", "內容較長、對話框放不下", "只需要確認一件事時用對話框"]),
  (id: "popover", group: "feedback", name: "彈出卡片", en: "Popover", desc: "點擊後在按鈕旁邊顯示的小卡片，可以放文字和按鈕。用原生 popover，點外面或按 Esc 自動關閉。", when: <String>["需要互動的補充內容，例如小表單、確認", "只是文字說明時用文字提示", "內容多到需要捲動時改用抽屜"]),
  (id: "result", group: "feedback", name: "結果頁", en: "Result", desc: "流程結束時告訴使用者結果：成功、失敗或需要等待。圖示彈出後打勾逐筆畫出。", when: <String>["付款、送出表單、註冊完成", "失敗時說明原因並提供下一步", "小操作的結果用通知就好"]),
  (id: "float-button", group: "general", name: "懸浮按鈕", en: "Float Button", desc: "固定在畫面角落的按鈕，放最常用的一個動作，或「回到頂部」。", when: <String>["頁面上最重要的單一動作，例如新增、客服", "長頁面的回到頂部", "一個頁面最多一個，太多會擋住內容"]),
  (id: "autocomplete", group: "entry", name: "自動完成", en: "Autocomplete", desc: "邊打字邊篩選建議，符合的字會標成珊瑚紅。可以用方向鍵選、Enter 確認。", when: <String>["選項很多，用下拉選擇要捲很久", "使用者大概知道要找什麼", "選項少於 7 個時直接用下拉選擇"]),
  (id: "input-number", group: "entry", name: "數字輸入", en: "Input Number", desc: "用加減按鈕調整數字，也能直接輸入。到達上下限時按鈕自動停用。", when: <String>["數量、人數、份數等小範圍整數", "需要精確數值又常常只差一兩個", "範圍大、不需要精確時用滑桿"]),
  (id: "color", group: "entry", name: "顏色選擇", en: "Color Picker", desc: "選顏色。自由選色用原生色票，品牌色限定時用預設色票（純 CSS）。", when: <String>["標籤、主題、圖表顏色設定", "品牌限定顏色時只給預設色票，避免選到不合規的顏色"]),
  (id: "otp", group: "entry", name: "驗證碼", en: "OTP Input", desc: "輸入簡訊或信箱收到的驗證碼。打一位自動跳下一格，可以一次貼上整串，錯誤時左右搖晃。", when: <String>["登入、付款的二次驗證", "固定位數的代碼", "長度不固定的密碼用一般輸入框"]),
  (id: "carousel", group: "display", name: "輪播", en: "Carousel", desc: "在同一個位置輪流顯示多張內容。用 scroll-snap，手機可以直接滑動，滑到一半放開會自動對齊。", when: <String>["首頁主視覺、商品圖片", "內容同等重要、不需要同時看到", "重要資訊不要放在第 2 張以後，多數人不會看"]),
  (id: "calendar", group: "display", name: "日曆", en: "Calendar", desc: "整個月份的日曆，可以切換月份與選日期。切換月份時日期往同方向滑入。", when: <String>["需要看到一整個月才好決定，例如訂房、預約", "只是輸入已知日期（生日）時用日期輸入框", "今天用藍色外框標示"]),
  (id: "tree", group: "display", name: "樹狀結構", en: "Tree", desc: "有階層的資料，例如資料夾、組織架構。用巢狀 details，不需要 JS。", when: <String>["檔案總管、分類、組織圖", "層級 3 層以內最好找", "只有兩層時用摺疊面板或側邊選單"]),
  (id: "image", group: "display", name: "圖片預覽", en: "Image", desc: "點縮圖放大檢視。大圖從縮圖的位置長出來（FLIP 動畫），關閉時縮回原位。", when: <String>["作品集、商品圖、附件縮圖", "縮圖太小看不清細節時", "裝飾用的圖片不需要放大"]),
  (id: "banner", group: "feedback", name: "公告列", en: "Banner", desc: "放在頁面最上方的全站公告，例如新功能、維護通知。關閉時往上淡出。", when: <String>["影響所有人的消息：維護、新版上線、優惠", "一次只放一則", "只跟某個區塊有關的訊息用警示"]),
  (id: "data-table", group: "display", name: "資料表格", en: "Data Table", desc: "可以排序、搜尋、勾選的表格。排序時每一列從舊位置滑到新位置（FLIP），看得出資料怎麼移動。", when: <String>["後台的資料管理頁：訂單、會員、文章", "需要批次操作時加勾選欄", "只是展示少量資料用一般表格就好"]),
  (id: "cascader", group: "entry", name: "級聯選擇", en: "Cascader", desc: "有階層的選項逐層選擇，例如縣市 → 區域。每選一層，右邊滑出下一欄。", when: <String>["地址、商品分類、組織部門", "層級 2–4 層", "只有一層時用下拉選擇"]),
